// CP español de 5 cifras (los de 4 cifras se completan con un 0 delante).
export function cpEspanol(o) {
  if (!o) return "";
  const pais = String(o.countryCode || "ES").toUpperCase();
  if (pais && pais !== "ES") return "";
  const d = String(o.postalCode || "").replace(/\D/g, "");
  return d.length === 4 ? "0" + d : d.length === 5 ? d : "";
}
export function zonaMontana(o) {
  const cp = cpEspanol(o);
  return CP_MONTANA.has(cp) ? "MONTAÑA" : CP_REMOTA.has(cp) ? "REMOTA" : null;
}
// Pedido de Furniture a CP de montaña sin el suplemento pagado: retenido.
export function montanaPendiente(o) {
  return !!(o && o.agencia === "FURNITURE" && !o.cancelado && zonaMontana(o) && !(o.suplementoMontana && o.suplementoMontana.pagado));
}
